verificationSql:
BEGIN;
SET LOCAL statement_timeout='10s';
DO $verify$
DECLARE actor uuid:=gen_random_uuid(); exposure uuid:=gen_random_uuid(); session uuid:=gen_random_uuid();
rid text:=substr(md5(gen_random_uuid()::text),1,22); token_a text:=substr(md5(gen_random_uuid()::text),1,22);
token_b text:=substr(md5(gen_random_uuid()::text),1,22); receipt jsonb; n integer;
BEGIN
INSERT INTO auth.users(id) VALUES(actor);
INSERT INTO public.profiles(id,handle,name,account_status) VALUES(actor,'ci_d_'||substr(replace(actor::text,'-',''),1,12),'CI synthetic dwell','active') ON CONFLICT(id) DO UPDATE SET account_status='active';
UPDATE public.feature_flags SET enabled=true WHERE flag='discovery_dwell_telemetry_enabled';
INSERT INTO public.rank_events(id,user_id,item_id,item_kind,position,surface,session_id,recommendation_id,features)
 VALUES(exposure,actor,'node/ci-dwell-receipt','place',2,'discovery',session,rid,jsonb_build_object('recommendationId',rid));
SET LOCAL ROLE service_role;
receipt:=public.admit_discovery_dwell(actor,exposure,rid,'node/ci-dwell-receipt',jsonb_build_array(jsonb_build_object('kind','active','ms',4200,'token',token_a)));
IF receipt IS DISTINCT FROM '{"ok":true,"recorded":1,"duplicates":0}'::jsonb THEN RAISE EXCEPTION 'service admission receipt mismatch'; END IF;
receipt:=public.admit_discovery_dwell(actor,exposure,rid,'node/ci-dwell-receipt',jsonb_build_array(jsonb_build_object('kind','active','ms',4200,'token',token_a)));
IF receipt IS DISTINCT FROM '{"ok":true,"recorded":0,"duplicates":1}'::jsonb THEN RAISE EXCEPTION 'duplicate receipt mismatch'; END IF;
BEGIN
 PERFORM public.admit_discovery_dwell(actor,exposure,rid,'node/ci-dwell-receipt',jsonb_build_array(jsonb_build_object('kind','active','ms',4300,'token',token_a),jsonb_build_object('kind','idle','ms',5000,'token',token_b)));
 RAISE EXCEPTION 'conflict unexpectedly admitted';
EXCEPTION WHEN OTHERS THEN IF SQLERRM <> 'dwell_receipt_conflict' THEN RAISE; END IF;
END;
SELECT count(*) INTO n FROM public.rank_events WHERE user_id=actor AND event_type='place_dwell';
IF n<>1 THEN RAISE EXCEPTION 'partial conflicting batch persisted'; END IF;
UPDATE public.feature_flags SET enabled=false WHERE flag='discovery_dwell_telemetry_enabled';
receipt:=public.admit_discovery_dwell(actor,exposure,rid,'node/ci-dwell-receipt',jsonb_build_array(jsonb_build_object('kind','idle','ms',5000,'token',token_b)));
IF receipt IS DISTINCT FROM '{"ok":false,"reason":"disabled"}'::jsonb THEN RAISE EXCEPTION 'disabled flag admitted'; END IF;
RESET ROLE;
IF has_function_privilege('anon','public.admit_discovery_dwell(uuid,uuid,text,text,jsonb)','EXECUTE')
 OR has_function_privilege('authenticated','public.admit_discovery_dwell(uuid,uuid,text,text,jsonb)','EXECUTE')
 OR (SELECT prosecdef FROM pg_proc WHERE oid='public.admit_discovery_dwell(uuid,uuid,text,text,jsonb)'::regprocedure)
THEN RAISE EXCEPTION 'service-only invoker authority mismatch'; END IF;
END $verify$;
ROLLBACK;
SELECT '4033 service-role receipt, exact duplicate, mixed conflict rollback, disabled flag and privilege assertions passed; fixtures rolled back' AS result, now() AS verified_at;
